<?php
require_once __DIR__ . '/includes/functions.php';
$page_title='Kalender Kegiatan';$active_page='calendar';
$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$monthStart=$month.'-01';$startTs=strtotime($monthStart);$endTs=strtotime('+1 month',$startTs);
$stmt=db()->prepare('SELECT a.*,u.name AS user_name FROM activities a JOIN users u ON u.id=a.user_id WHERE a.activity_date>=:start_date AND a.activity_date<:end_date ORDER BY a.activity_date,a.activity_time,a.id');$stmt->execute([':start_date'=>date('Y-m-d',$startTs),':end_date'=>date('Y-m-d',$endTs)]);$rows=$stmt->fetchAll();
$byDate=[];foreach($rows as $r)$byDate[$r['activity_date']][]=$r;
$prev=date('Y-m',strtotime('-1 month',$startTs));$next=date('Y-m',strtotime('+1 month',$startTs));$firstDow=(int)date('N',$startTs);$days=(int)date('t',$startTs);$today=date('Y-m-d');$months=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
require __DIR__ . '/partials/header.php';
