<?php for($day=1;$day<=$days;$day++):$d=date('Y-m-d',strtotime($monthStart.' +'.($day-1).' days'));$items=$byDate[$d]??[]; ?><div class="calendar-cell <?= $d===$today?'today':'' ?> <?= $items?'has-items':'' ?>"><div class="day-num"><?= $day ?></div><?php if($items): ?><div class="day-count"><?= count($items) ?> kegiatan</div><div class="day-dots"><i></i><i></i></div><div class="day-tooltip"><strong><?= e(format_date_id($d)) ?></strong><?php foreach(array_slice($items,0,4) as $item): ?><a href="activity_view.php?id=<?= (int)$item['id'] ?>"><?= e($item['title']) ?> · <?= e($item['user_name']) ?></a><?php endforeach; ?></div><?php endif; ?></div><?php endfor; ?>
</div></section><section class="panel"><div class="panel-head"><div><h3>Kegiatan bulan ini</h3><p><?= count($rows) ?> catatan pada <?= e($months[(int)date('n',$startTs)-1]) ?>.</p></div></div><div class="calendar-list"><?php if(!$rows): ?><div class="empty"><strong>Belum ada kegiatan bulan ini.</strong><span>Kegiatan baru akan muncul di sini.</span></div><?php endif; ?><?php foreach($rows as $row): ?><a class="calendar-row" href="activity_view.php?id=<?= (int)$row['id'] ?>"><div class="calendar-date"><strong><?= e(date('d',strtotime($row['activity_date']))) ?></strong><span><?= e(date('M',strtotime($row['activity_date']))) ?></span></div><div><strong><?= e($row['title']) ?></strong><span><?= e($row['activity_time']?format_time($row['activity_time']):'Tanpa waktu') ?> · <?= e($row['category']) ?> · <?= e($row['user_name']) ?></span></div><span class="calendar-open">↗</span></a><?php endforeach; ?></div></section></div>
